INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Signal immer mit Lichtgeschwindigkeit übertragen wird?', 2, '[{"text": "Nein", "correct": true, "because": "In Medien durch Verkürzungsfaktor reduziert"}, {"text": "Ja", "correct": false, "because": "Materialabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geschwindigkeit beschreibt die Ausbreitung eines Wellenpakets?', 3, '[{"text": "Gruppengeschwindigkeit", "correct": true, "because": "Bewegung der Einhüllenden"}, {"text": "Phasengeschwindigkeit", "correct": false, "because": "Einzelne Wellen"}, {"text": "Lichtgeschwindigkeit", "correct": false, "because": "Maximalgrenze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Übertragung in Kabeln?', 5, '[{"text": "Verkürzungsfaktor", "correct": true, "because": "Reduziert Geschwindigkeit"}, {"text": "Material", "correct": true, "because": "Bestimmt Leitfähigkeit"}, {"text": "Kabeldicke", "correct": false, "because": "Sekundär"}, {"text": "Farbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Frontgeschwindigkeit ist immer kleiner als die Lichtgeschwindigkeit. b) Sie ist identisch mit der Gruppengeschwindigkeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, unterschiedlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Berechnung der Signalübertragung?', 4, '[{"text": "Medium", "correct": false, "because": "Beeinflusst Geschwindigkeit"}, {"text": "Verkürzungsfaktor", "correct": false, "because": "Bestimmt Reduktion"}, {"text": "Kabelgewicht", "correct": true, "because": "Kein Übertragungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Übertragung in Glasfaser die Lichtgeschwindigkeit erreicht?', 2, '[{"text": "Nein", "correct": true, "because": "Materialbedingt reduziert"}, {"text": "Ja", "correct": false, "because": "Immer geringer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geschwindigkeit ist für die Informationsübertragung entscheidend?', 4, '[{"text": "Signalgeschwindigkeit", "correct": true, "because": "Trägt Information"}, {"text": "Phasengeschwindigkeit", "correct": false, "because": "Kann überlichtschnell sein"}, {"text": "Wellenlänge", "correct": false, "because": "Kein Geschwindigkeitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Gruppengeschwindigkeit immer die Lichtgeschwindigkeit übertrifft. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kann kleiner oder gleich sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer überlichtschnell"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Signalgeschwindigkeit in Kabeln gleich der Lichtgeschwindigkeit?', 2, '[{"text": "Nein", "correct": true, "because": "Verkürzungsfaktor reduziert"}, {"text": "Ja", "correct": false, "because": "Materialabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Medien beeinflussen die Signalübertragung?', 5, '[{"text": "Kupferkabel", "correct": true, "because": "Hoher Verkürzungsfaktor"}, {"text": "Glasfaser", "correct": true, "because": "Schneller, aber reduziert"}, {"text": "Vakuum", "correct": true, "because": "Lichtgeschwindigkeit"}, {"text": "Papier", "correct": false, "because": "Kein Übertragungsmedium"}, {"text": "Holz", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Analyse der Signalübertragung?', 4, '[{"text": "Mediumseigenschaften", "correct": true, "because": "Bestimmen Geschwindigkeit"}, {"text": "Kabeldesign", "correct": false, "because": "Kosmetisch"}, {"text": "Schnelle Berechnung", "correct": false, "because": "Genauigkeit wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Signalgeschwindigkeit ist kleiner als Lichtgeschwindigkeit. b) Sie ist immer gleich der Gruppengeschwindigkeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, kann abweichen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Analyse der Signalübertragung?', 3, '[{"text": "Verkürzungsfaktor", "correct": false, "because": "Bestimmt Geschwindigkeit"}, {"text": "Material", "correct": false, "because": "Beeinflusst Ausbreitung"}, {"text": "Kabelbeschriftung", "correct": true, "because": "Kein Übertragungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Übertragung in einem Kupferkabel berechne?', 4, '[{"text": "Lichtgeschwindigkeit mit Verkürzungsfaktor multiplizieren", "correct": true, "because": "Gibt effektive Geschwindigkeit"}, {"text": "Nur Lichtgeschwindigkeit nutzen", "correct": false, "because": "Ignoriert Medium"}, {"text": "Ohne Faktor", "correct": false, "because": "Falsches Ergebnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Signalgeschwindigkeit in allen Medien gleich ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Materialabhängig"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Medien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Medium hat die höchste Signalübertragung?', 4, '[{"text": "Vakuum", "correct": true, "because": "Lichtgeschwindigkeit"}, {"text": "Kupferkabel", "correct": false, "because": "Reduziert durch Faktor"}, {"text": "Glasfaser", "correct": false, "because": "Leicht reduziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Gruppengeschwindigkeit die Lichtgeschwindigkeit übertreffen?', 2, '[{"text": "Ja", "correct": true, "because": "In manchen Medien möglich"}, {"text": "Nein", "correct": false, "because": "Nicht immer kleiner"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können die Signalübertragung beeinträchtigen?', 5, '[{"text": "Absorption", "correct": true, "because": "Schwächt Signal"}, {"text": "Dispersion", "correct": true, "because": "Verzerrt Signal"}, {"text": "Frequenz", "correct": true, "because": "Beeinflusst Geschwindigkeit"}, {"text": "Kabelgewicht", "correct": false, "because": "Irrelevant"}, {"text": "Farbe", "correct": false, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Signalübertragung unwichtig?', 3, '[{"text": "Material", "correct": false, "because": "Bestimmt Geschwindigkeit"}, {"text": "Verkürzungsfaktor", "correct": false, "because": "Reduziert Lichtgeschwindigkeit"}, {"text": "Kabelbeschriftung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich die Signalübertragung in Glasfaser analysiere?', 4, '[{"text": "Brechungsindex und Verkürzungsfaktor prüfen", "correct": true, "because": "Bestimmen Geschwindigkeit"}, {"text": "Nur Kabelgewicht prüfen", "correct": false, "because": "Irrelevant"}, {"text": "Ohne Analyse", "correct": false, "because": "Unpräzise"}]');
